import numpy as np
from numba import njit


@njit(cache=True)
def _simplex_proj_loop(y, s):
    """Numba JIT-compiled loop: find rho, compute theta, and project.

    s must be y sorted in descending order.
    """
    n = y.shape[0]
    cs = 0.0
    rho = 0
    cs_rho = 0.0
    for i in range(n):
        cs += s[i]
        # Condition: s[i] > (cs - 1) / (i + 1)  <=>  s[i] * (i + 1) > cs - 1
        if s[i] * (i + 1) > cs - 1.0:
            rho = i
            cs_rho = cs
    theta = (cs_rho - 1.0) / (rho + 1)
    return np.maximum(y - theta, 0.0)


class Solver:
    def __init__(self):
        # Pre-compile the numba function so compilation time is excluded
        _simplex_proj_loop(
            np.array([1.0, 2.0, 3.0]),
            np.array([3.0, 2.0, 1.0]),
        )

    def solve(self, problem, **kwargs):
        y = np.array(problem["y"], dtype=np.float64)
        # Use numpy's fast C sort; -np.sort(-y) gives descending order
        s = -np.sort(-y)
        x = _simplex_proj_loop(y, s)
        return {"solution": x}

