import numpy as np
from numba import njit


@njit(cache=True)
def _proj_simplex(y, s):
    """Find rho, compute theta, and project. s must be y sorted ascending."""
    n = y.shape[0]
    cs = 0.0
    rho = 0
    cs_rho = 0.0
    idx = n - 1
    for i in range(n):
        val = s[idx]
        cs += val
        if val > (cs - 1.0) / (i + 1):
            rho = i
            cs_rho = cs
        idx -= 1
    theta = (cs_rho - 1.0) / (rho + 1)
    return np.maximum(y - theta, 0.0)


class Solver:
    def __init__(self):
        y = np.array([1.0, 2.0, 3.0])
        _proj_simplex(y, np.sort(y))

    def solve(self, problem, **kwargs):
        y = np.array(problem["y"], dtype=np.float64)
        s = np.sort(y)
        x = _proj_simplex(y, s)
        return {"solution": x}

