import numpy as np
from numba import njit


@njit(cache=True)
def _solve_bisect(y):
    """Binary search for the optimal threshold theta, O(n * iter)."""
    n = y.shape[0]

    # Find min and max in one pass
    lo = y[0]
    hi = y[0]
    for i in range(1, n):
        if y[i] < lo:
            lo = y[i]
        if y[i] > hi:
            hi = y[i]
    lo -= 1.0

    for _ in range(50):
        mid = (lo + hi) * 0.5
        s = 0.0
        for i in range(n):
            if y[i] > mid:
                s += y[i] - mid
        if s > 1.0:
            lo = mid
        else:
            hi = mid

    theta = hi
    result = np.empty(n)
    for i in range(n):
        diff = y[i] - theta
        result[i] = diff if diff > 0.0 else 0.0
    return result


class Solver:
    def __init__(self):
        _solve_bisect(np.array([1.0, 2.0, 3.0]))

    def solve(self, problem, **kwargs):
        y = np.array(problem["y"], dtype=np.float64)
        x = _solve_bisect(y)
        return {"solution": x}

